create extension if not exists pgcrypto;
create table if not exists tenants(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,status text not null default 'active',created_at timestamptz not null default now());
create table if not exists users(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),email text not null,password_hash text not null,name text not null,status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,email));
create table if not exists roles(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id),name text not null,unique(tenant_id,name));
create table if not exists permissions(id uuid primary key default gen_random_uuid(),code text unique not null);
create table if not exists role_permissions(role_id uuid references roles(id) on delete cascade,permission_id uuid references permissions(id) on delete cascade,primary key(role_id,permission_id));
create table if not exists audit_log(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),user_id uuid references users(id),action text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists audit_tenant_created on audit_log(tenant_id,created_at desc);
create table if not exists categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),category_id uuid references categories(id),sku text not null,name text not null,unit text not null default 'PCS',mrp numeric(14,2) not null default 0,cost_price numeric(14,2) not null default 0,selling_price numeric(14,2) not null default 0,gst_rate numeric(5,2) not null default 0,pack_size numeric(14,3) not null default 1,active boolean not null default true,created_at timestamptz default now(),unique(tenant_id,sku));
create table if not exists customers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),code text,name text not null,customer_type text not null default 'retailer',phone text,address text,territory text,credit_limit numeric(14,2) default 0,active boolean default true,created_at timestamptz default now());
create table if not exists warehouses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,location text,active boolean default true,created_at timestamptz default now());
create table if not exists inventory_ledger(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),warehouse_id uuid not null references warehouses(id),product_id uuid not null references products(id),quantity numeric(18,3) not null,unit_cost numeric(14,2) not null default 0,transaction_type text not null,reference_type text,reference_id uuid,idempotency_key text,created_at timestamptz default now(),unique(tenant_id,idempotency_key));
create index if not exists inventory_product on inventory_ledger(tenant_id,product_id,warehouse_id,created_at);
create table if not exists orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),status text not null default 'draft',order_date timestamptz default now(),subtotal numeric(14,2) default 0,tax numeric(14,2) default 0,total numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists order_lines(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id uuid not null references products(id),quantity numeric(18,3) not null,unit_price numeric(14,2) not null,tax_rate numeric(5,2) default 0);
create table if not exists dispatches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),order_id uuid references orders(id),warehouse_id uuid references warehouses(id),status text not null default 'pending',dispatched_at timestamptz,created_at timestamptz default now());
create table if not exists distributors(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,code text not null,territory text,credit_limit numeric(14,2) default 0,created_at timestamptz default now(),unique(tenant_id,code));
create table if not exists wholesalers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,code text not null,territory text,created_at timestamptz default now(),unique(tenant_id,code));
create table if not exists sales_executives(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,phone text,territory text,distributor_id uuid references distributors(id),target numeric(14,2) default 0,active boolean default true,created_at timestamptz default now());
create table if not exists schemes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,scheme_type text not null,rule jsonb not null default '{}',active boolean default true,created_at timestamptz default now());
create table if not exists attendance(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sales_executive_id uuid not null references sales_executives(id),work_date date not null,check_in timestamptz,check_out timestamptz,latitude numeric(10,7),longitude numeric(10,7),accuracy_m numeric(10,2),photo_object text,created_at timestamptz default now(),unique(tenant_id,sales_executive_id,work_date));
create table if not exists dsr(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sales_executive_id uuid not null references sales_executives(id),customer_id uuid references customers(id),visit_at timestamptz default now(),latitude numeric(10,7),longitude numeric(10,7),photo_object text,notes text,order_id uuid references orders(id),idempotency_key text,created_at timestamptz default now(),unique(tenant_id,idempotency_key));
create table if not exists invoices(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),order_id uuid references orders(id),invoice_no text not null,invoice_date date not null default current_date,subtotal numeric(14,2) default 0,cgst numeric(14,2) default 0,sgst numeric(14,2) default 0,igst numeric(14,2) default 0,total numeric(14,2) default 0,status text default 'open',created_at timestamptz default now(),unique(tenant_id,invoice_no));
create table if not exists collections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),customer_id uuid references customers(id),invoice_id uuid references invoices(id),amount numeric(14,2) not null,payment_mode text not null,reference_no text,received_at timestamptz default now(),created_at timestamptz default now());
create table if not exists ledger_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),code text not null,name text not null,account_type text not null,unique(tenant_id,code));
create table if not exists journal_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),reference_type text,reference_id uuid,entry_date date default current_date,memo text,created_at timestamptz default now());
create table if not exists journal_lines(id uuid primary key default gen_random_uuid(),journal_id uuid not null references journal_entries(id) on delete cascade,account_id uuid not null references ledger_accounts(id),debit numeric(14,2) default 0,credit numeric(14,2) default 0,check(debit>=0 and credit>=0),check(not(debit>0 and credit>0)));
create table if not exists alerts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),alert_type text not null,severity text not null default 'medium',entity_type text,entity_id uuid,description text not null,status text default 'open',resolution_notes text,created_at timestamptz default now(),resolved_at timestamptz);
create table if not exists forecast_snapshots(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),product_id uuid references products(id),period_start date not null,period_end date not null,forecast_qty numeric(18,3) not null,method text not null,created_at timestamptz default now());
create table if not exists api_keys(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,key_hash text not null,scopes jsonb not null default '[]',last_used_at timestamptz,created_at timestamptz default now(),revoked_at timestamptz);
create table if not exists webhooks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),url text not null,events jsonb not null default '[]',secret_hash text,active boolean default true,created_at timestamptz default now());
create table if not exists integration_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),provider text not null,event_type text not null,payload jsonb not null,attempts int default 0,status text default 'pending',last_error text,created_at timestamptz default now());
create table if not exists raw_materials(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),sku text not null,name text not null,unit text not null default 'KG',cost_price numeric(14,2) default 0,active boolean default true,created_at timestamptz default now(),unique(tenant_id,sku));
create table if not exists boms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),finished_product_id uuid not null references products(id),version text not null,output_qty numeric(18,3) not null default 1,active boolean default true,created_at timestamptz default now());
create table if not exists bom_lines(id uuid primary key default gen_random_uuid(),bom_id uuid not null references boms(id) on delete cascade,raw_material_id uuid not null references raw_materials(id),quantity numeric(18,3) not null,wastage_pct numeric(5,2) default 0);
create table if not exists production_orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),bom_id uuid not null references boms(id),warehouse_id uuid references warehouses(id),planned_qty numeric(18,3) not null,status text not null default 'planned',started_at timestamptz,completed_at timestamptz,created_at timestamptz default now());
create table if not exists production_consumption(id uuid primary key default gen_random_uuid(),production_order_id uuid not null references production_orders(id) on delete cascade,raw_material_id uuid not null references raw_materials(id),quantity numeric(18,3) not null);
create table if not exists finished_goods(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),production_order_id uuid references production_orders(id),product_id uuid not null references products(id),batch_no text,quantity numeric(18,3) not null,quality_status text default 'pending',created_at timestamptz default now());
